/** An ISO 4217 code: always three upper-case letters. Never null, never lower case. */
export type CurrencyCode = string;

export interface Invoice {
  id: string;
  number: string;
  currency: CurrencyCode;
  /** The amount in minor units, for example cents. */
  amountMinor: number;
}

export class ContractError extends Error {}

/** The invoices of the account. Rejects with ContractError when the service returns one that breaks this contract. */
export function fetchInvoices(transport: { get(path: string): Promise<unknown[]> }): Promise<Invoice[]>;
